<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue'
import {ArrowRight,Check,Clock,Close,Connection,DataLine,Refresh,Setting,Warning} from '@element-plus/icons-vue'
import type {NodeMonitorCommand,NodeMonitorIssue,NodeMonitorPhase,NodeMonitorPolicy,NodeMonitorSnapshot} from '../../electron/shared/node-monitor'

const state=ref<NodeMonitorSnapshot>(),selectedId=ref(''),filter=ref<'active'|'all'|'completed'>('active'),error=ref(''),busy=ref(''),loading=ref(false),settingsOpen=ref(false),budgetDirty=ref(false)
const budget=reactive({maxAttemptsPerIssue:2,maxRepairsPerDay:6,analysisTimeoutSeconds:120})
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false,revision=0
const terminal=new Set<NodeMonitorPhase>(['applied','resolved','dismissed','superseded'])
const working=new Set<NodeMonitorPhase>(['analyzing','repairing','verifying'])
const labels:Record<NodeMonitorPhase,string>={queued:'等待分析',analyzing:'分析中',repairing:'修复中',verifying:'验证中',applied:'已热更新',resolved:'已恢复',waiting:'待处理',failed:'修复失败',dismissed:'已忽略',superseded:'已过期'}
const causeLabels={transient:'临时故障',verification:'验收问题',module:'能力模块',permission:'权限限制',configuration:'配置问题',application:'应用代码',unknown:'原因待确认'}
const issues=computed(()=>state.value?.issues||[])
const active=computed(()=>issues.value.filter(issue=>!terminal.has(issue.phase)))
const completed=computed(()=>issues.value.filter(issue=>issue.phase==='applied'||issue.phase==='resolved'))
const processed=computed(()=>issues.value.filter(issue=>terminal.has(issue.phase)))
const visible=computed(()=>filter.value==='active'?active.value:filter.value==='completed'?processed.value:issues.value)
const selected=computed(()=>visible.value.find(issue=>issue.id===selectedId.value)||visible.value[0])
const running=computed(()=>issues.value.find(issue=>issue.id===state.value?.runningId))
const waiting=computed(()=>active.value.filter(issue=>issue.phase==='waiting'||issue.phase==='failed').length)
const canRetry=computed(()=>!!selected.value&&['waiting','failed','dismissed'].includes(selected.value.phase))
const time=(value?:string)=>value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}):'尚无记录'
const safeText=(value?:string)=>String(value||'').replace(/\b(Bearer\s+)[A-Za-z0-9._~+/=-]+/gi,'$1[已隐藏]').replace(/((?:api[-_ ]?key|authorization|password|secret)\s*[:=]\s*)[^\s,;]+/gi,'$1[已隐藏]')
const sourceLabel=(issue:NodeMonitorIssue)=>issue.source==='module'?'能力模块':issue.source==='session'?'会话执行':'任务节点'
function accept(next:NodeMonitorSnapshot){
 state.value=next
 if(!budgetDirty.value)Object.assign(budget,{maxAttemptsPerIssue:next.policy.maxAttemptsPerIssue,maxRepairsPerDay:next.policy.maxRepairsPerDay,analysisTimeoutSeconds:next.policy.analysisTimeoutSeconds})
}
function schedule(){clearTimeout(timer);if(!disposed&&document.visibilityState==='visible')timer=setTimeout(()=>void load(),2000)}
async function load(){
 if(disposed||document.visibilityState!=='visible')return
 if(loading.value||busy.value){schedule();return}
 loading.value=true;const current=++revision
 try{const next=await window.myplane.localAiStudio('nodeMonitorState');if(!disposed&&current===revision){accept(next);error.value=''}}
 catch(cause){if(!disposed&&current===revision)error.value=safeText(cause instanceof Error?cause.message:String(cause))}
 finally{loading.value=false;schedule()}
}
async function command(value:NodeMonitorCommand,key:string){
 if(busy.value)return
 busy.value=key;error.value='';clearTimeout(timer);const current=++revision
 try{const next=await window.myplane.localAiStudio('nodeMonitorCommand',value);if(!disposed&&current===revision)accept(next)}
 catch(cause){if(!disposed&&current===revision)error.value=safeText(cause instanceof Error?cause.message:String(cause))}
 finally{busy.value='';schedule()}
}
async function toggle(key:'enabled'|'autoRepair'|'autoApply'){
 if(!state.value)return
 await command({action:'policy',policy:{...state.value.policy,[key]:!state.value.policy[key]}},key)
}
async function saveBudget(){
 if(!state.value)return
 const policy:NodeMonitorPolicy={...state.value.policy,...budget}
 await command({action:'policy',policy},'budget')
 if(!error.value){budgetDirty.value=false;accept(state.value!)}
}
async function openGraph(issue:NodeMonitorIssue){
 if(!issue.sessionId)return
 try{await window.myplane.runtimeGraphWindow('open',issue.sessionId)}catch(cause){error.value=safeText(cause instanceof Error?cause.message:String(cause))}
}
function visibilityChanged(){clearTimeout(timer);if(document.visibilityState==='visible')void load()}
watch(visible,list=>{if(!list.some(issue=>issue.id===selectedId.value))selectedId.value=list[0]?.id||''})
onMounted(()=>{document.addEventListener('visibilitychange',visibilityChanged);void load()})
onBeforeUnmount(()=>{disposed=true;revision++;clearTimeout(timer);document.removeEventListener('visibilitychange',visibilityChanged)})
</script>

<template>
 <main class="node-monitor-page" aria-label="运行监控">
  <header class="monitor-heading">
   <div><div class="monitor-eyebrow"><DataLine/>后台运行保障</div><h1>运行监控</h1><p>从错误节点追踪原因，验证修复结果，再应用可用的能力更新。</p></div>
   <div class="monitor-heading-actions">
    <button class="monitor-button" :class="{active:settingsOpen}" :aria-expanded="settingsOpen" aria-controls="monitor-settings" @click="settingsOpen=!settingsOpen"><Setting/>设置</button>
    <button class="monitor-button" :disabled="!state||!!busy" @click="command({action:'scan'},'scan')"><Refresh :class="{spinning:busy==='scan'}"/>{{busy==='scan'?'检查中…':'立即检查'}}</button>
   </div>
  </header>
  <div v-if="error" class="monitor-error" role="alert"><Warning/><span>{{error}}</span><button aria-label="关闭监控提示" @click="error=''"><Close/></button></div>
  <div v-if="!state" class="monitor-empty monitor-loading"><DataLine/><h2>{{error?'监控状态暂时不可用':'正在读取监控状态'}}</h2><p>{{error?'可以重新读取，运行中的会话不会受影响。':'连接应用内的后台监控器…'}}</p><button v-if="error" class="monitor-button" :disabled="loading" @click="load">重新读取</button></div>
  <template v-else>
   <section class="monitor-status-bar" aria-label="监控状态">
    <div class="monitor-status-main"><span class="monitor-status-orbit" :class="{enabled:state.policy.enabled,running:!!running}"><DataLine/></span><div><strong>{{state.policy.enabled?'监控已开启':'监控已暂停'}}</strong><span>{{running?labels[running.phase]+' · '+running.title:state.policy.enabled?'等待新的节点执行结果':'暂停分析与修复，已有记录保留'}}</span></div></div>
    <button class="monitor-switch" role="switch" aria-label="启用运行监控" :aria-checked="state.policy.enabled" :disabled="!!busy" @click="toggle('enabled')"><span/></button>
   </section>
   <section v-if="settingsOpen" id="monitor-settings" class="monitor-settings" aria-label="监控设置">
    <div class="monitor-policy-row"><div><strong>自动修复</strong><p>对满足条件的问题尝试恢复；次数受下方预算限制。</p></div><button class="monitor-switch" role="switch" aria-label="启用自动修复" :aria-checked="state.policy.autoRepair" :disabled="!!busy" @click="toggle('autoRepair')"><span/></button></div>
    <div class="monitor-policy-row"><div><strong>自动应用能力更新</strong><p>候选通过验证后切换能力版本，保留旧版记录。</p></div><button class="monitor-switch" role="switch" aria-label="自动应用能力热更新" :aria-checked="state.policy.autoApply" :disabled="!!busy" @click="toggle('autoApply')"><span/></button></div>
    <form class="monitor-budget" @submit.prevent="saveBudget"><label>每个问题最多修复<input v-model.number="budget.maxAttemptsPerIssue" type="number" min="1" max="5" required :disabled="!!busy" @input="budgetDirty=true"/><small>次</small></label><label>每日最多修复<input v-model.number="budget.maxRepairsPerDay" type="number" min="1" max="50" required :disabled="!!busy" @input="budgetDirty=true"/><small>次</small></label><label>单次处理时限<input v-model.number="budget.analysisTimeoutSeconds" type="number" min="15" max="300" required :disabled="!!busy" @input="budgetDirty=true"/><small>秒</small></label><button class="monitor-button" :disabled="!budgetDirty||!!busy" type="submit">{{busy==='budget'?'保存中…':'保存预算'}}</button></form>
   </section>
   <section class="monitor-metrics" aria-label="监控统计"><div><span>待处理问题</span><strong>{{active.length}}</strong><small>{{waiting?waiting+' 项需要进一步处理':'按队列逐项处理'}}</small></div><div><span>已恢复 / 已更新</span><strong>{{completed.length}}</strong><small>以实际验证结果为准</small></div><div><span>今日修复次数</span><strong>{{state.repairsToday}}<em>/ {{state.policy.maxRepairsPerDay}}</em></strong><small>每日预算按 UTC 计算</small></div><div class="monitor-last-check"><span>最近检查</span><strong>{{time(state.lastScanAt)}}</strong><small>{{state.model?'分析模型 · '+safeText(state.model):'使用当前可用的模型配置'}}</small></div></section>
   <div class="monitor-workspace">
    <section class="monitor-queue" aria-label="错误节点队列">
     <header><h2>问题记录 <span>{{issues.length}}</span></h2><button class="monitor-icon" aria-label="刷新监控记录" :disabled="loading||!!busy" @click="load"><Refresh :class="{spinning:loading}"/></button></header>
     <div class="monitor-filters" role="group" aria-label="筛选监控记录"><button :class="{selected:filter==='active'}" :aria-pressed="filter==='active'" @click="filter='active'">待处理</button><button :class="{selected:filter==='completed'}" :aria-pressed="filter==='completed'" @click="filter='completed'">已处理</button><button :class="{selected:filter==='all'}" :aria-pressed="filter==='all'" @click="filter='all'">全部</button></div>
     <div v-if="!visible.length" class="monitor-queue-empty"><Check/><strong>{{issues.length?'当前筛选下没有问题':'尚未发现错误节点'}}</strong><p>{{state.policy.enabled?'新问题会自动出现在这里。':'开启监控后继续分析待处理问题。'}}</p></div>
     <div v-else class="monitor-issue-list"><button v-for="issue in visible" :key="issue.id" class="monitor-issue" :class="{selected:issue.id===selected?.id}" :aria-pressed="issue.id===selected?.id" @click="selectedId=issue.id"><div class="monitor-issue-top"><span class="monitor-phase" :data-phase="issue.phase"><i/>{{labels[issue.phase]}}</span><time>{{time(issue.updatedAt)}}</time></div><strong>{{safeText(issue.title)}}</strong><p>{{safeText(issue.diagnosis?.summary||issue.error)}}</p><div class="monitor-issue-bottom"><span>{{safeText(issue.sessionTitle)||sourceLabel(issue)}}</span><small>{{issue.occurrences}} 次发生</small></div></button></div>
    </section>
    <section class="monitor-detail" aria-label="节点诊断详情">
     <template v-if="selected">
      <header><div class="monitor-detail-title"><span class="monitor-eyebrow">{{sourceLabel(selected)}}</span><h2>{{safeText(selected.title)}}</h2><p>{{safeText(selected.sessionTitle)||selected.moduleId||'应用运行记录'}} · {{time(selected.createdAt)}}</p></div><span class="monitor-phase" :data-phase="selected.phase"><i/>{{labels[selected.phase]}}</span></header>
      <div class="monitor-detail-actions"><button v-if="selected.sessionId" class="monitor-button" @click="openGraph(selected)"><Connection/>查看 3D 运行图<ArrowRight/></button><button v-if="canRetry" class="monitor-button" :disabled="!!busy" @click="command({action:'retry',id:selected.id},'retry')"><Refresh/>重新分析并处理</button><button v-if="!terminal.has(selected.phase)&&!working.has(selected.phase)" class="monitor-button subtle" :disabled="!!busy" @click="command({action:'dismiss',id:selected.id},'dismiss')">忽略此问题</button></div>
      <p v-if="canRetry" class="monitor-action-note">手动处理会尝试符合条件的修复，仍遵守原权限和预算。</p>
      <div class="monitor-diagnosis" :class="{pending:!selected.diagnosis}"><div class="monitor-section-label"><span>{{selected.diagnosis?'原因分析':'处理状态'}}</span><span v-if="selected.diagnosis" class="monitor-cause">{{causeLabels[selected.diagnosis.cause]}}</span></div><p>{{safeText(selected.diagnosis?.summary||selected.message)||'等待后台分析当前问题。'}}</p><div v-if="selected.diagnosis?.nextStep" class="monitor-next-step"><ArrowRight/><span>{{safeText(selected.diagnosis.nextStep)}}</span></div></div>
      <div v-if="selected.message&&selected.diagnosis" class="monitor-result" role="status"><span>最新处理结果</span><p>{{safeText(selected.message)}}</p></div>
      <div v-if="selected.fromVersion||selected.toVersion" class="monitor-version"><span>能力版本</span><div><code>{{selected.fromVersion||'原版本未记录'}}</code><ArrowRight/><code>{{selected.toVersion||'等待验证'}}</code></div><small>修复 {{selected.attempts}} 次<template v-if="selected.jobId"> · 任务 {{selected.jobId}}</template></small></div>
      <details class="monitor-error-details"><summary>原始错误 <span>{{selected.occurrences}} 次发生 · {{selected.attempts}} 次修复</span></summary><pre>{{safeText(selected.error)}}</pre><dl><template v-if="selected.nodeId"><dt>节点</dt><dd>{{selected.nodeId}}</dd></template><template v-if="selected.taskId"><dt>任务</dt><dd>{{selected.taskId}}</dd></template><template v-if="selected.moduleId"><dt>能力模块</dt><dd>{{selected.moduleId}}</dd></template></dl></details>
      <section class="monitor-history" aria-label="修复过程"><h3>处理过程</h3><ol v-if="selected.events.length"><li v-for="(event,index) in [...selected.events].reverse()" :key="index"><i :data-phase="event.phase"/><div><strong>{{labels[event.phase]}}</strong><time>{{time(event.at)}}</time><p>{{safeText(event.message)}}</p></div></li></ol><p v-else class="monitor-muted">暂无处理记录。</p></section>
     </template>
     <div v-else class="monitor-empty"><span class="monitor-empty-icon"><DataLine/></span><h2>{{filter==='active'?'运行情况，持续可见':'查看处理结果'}}</h2><p>选择一条问题记录，查看错误节点、原因分析和修复过程。</p><div class="monitor-flow"><span>发现错误</span><ArrowRight/><span>分析与修复</span><ArrowRight/><span>验证与更新</span></div></div>
    </section>
   </div>
   <footer class="monitor-footnote"><Clock/><p>{{safeText(state.hotUpdateNote)||'可版本化的能力通过验证后应用更新；应用主进程代码需通过应用更新生效。'}}监控由应用后台执行，离开本页不会停止。</p></footer>
  </template>
 </main>
</template>

<style scoped>
.node-monitor-page{flex:1;min-width:0;min-height:0;overflow:auto;padding:30px 32px 22px;color:var(--s-text);background:var(--s-bg);--monitor-dim:color-mix(in srgb,var(--s-dim) 82%,var(--s-text));--monitor-green:light-dark(#246f5b,#8cd8b7);--monitor-amber:light-dark(#8b5e18,#e9c784);--monitor-red:light-dark(#b04444,#ec9999)}
.monitor-heading,.monitor-heading-actions,.monitor-status-bar,.monitor-status-main,.monitor-policy-row,.monitor-queue>header,.monitor-issue-top,.monitor-issue-bottom,.monitor-detail>header,.monitor-detail-actions,.monitor-section-label,.monitor-version>div,.monitor-error-details summary,.monitor-history li>div>strong,.monitor-flow,.monitor-footnote{display:flex;align-items:center}
.monitor-heading{justify-content:space-between;gap:18px;margin-bottom:24px}.monitor-heading h1{font-size:25px;font-weight:650;letter-spacing:-.6px;margin:8px 0}.monitor-heading p{margin:0;font-size:12px;color:var(--monitor-dim);line-height:1.7}.monitor-eyebrow{display:flex;align-items:center;gap:6px;font-size:10px;color:var(--monitor-dim);letter-spacing:.7px}.monitor-eyebrow svg{width:13px;height:13px}.monitor-heading-actions{gap:8px}.node-monitor-page button{font:inherit;cursor:pointer;color:inherit}.node-monitor-page button:disabled{opacity:.45;cursor:default}.node-monitor-page button:focus-visible,.node-monitor-page input:focus-visible,.node-monitor-page summary:focus-visible{outline:2px solid var(--s-accent);outline-offset:3px}.monitor-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:34px;padding:7px 12px;border:1px solid var(--s-border);border-radius:8px;background:var(--s-panel);font-size:11px!important;white-space:nowrap}.monitor-button svg{width:14px;height:14px}.monitor-button:hover:not(:disabled),.monitor-button.active{background:var(--s-accent-soft);border-color:var(--s-accent)}.monitor-button.subtle{background:transparent;border-color:transparent;color:var(--monitor-dim)}
.monitor-error{display:flex;align-items:center;gap:9px;padding:12px 14px;background:color-mix(in srgb,var(--monitor-red) 9%,var(--s-panel));color:var(--monitor-red);border:1px solid color-mix(in srgb,var(--monitor-red) 25%,var(--s-border));border-radius:9px;font-size:12px;margin-bottom:16px}.monitor-error>svg{width:17px;flex-shrink:0}.monitor-error>span{flex:1;overflow-wrap:anywhere}.monitor-error button{border:0;background:transparent;padding:3px;display:flex}.monitor-error button svg{width:14px}
.monitor-status-bar{justify-content:space-between;gap:20px;border:1px solid var(--s-border);border-radius:12px;background:var(--s-panel);padding:18px 20px}.monitor-status-main{min-width:0;gap:13px}.monitor-status-main strong{display:block;font-size:13px;font-weight:600}.monitor-status-main span:not(.monitor-status-orbit){display:block;font-size:11px;color:var(--monitor-dim);margin-top:5px;overflow-wrap:anywhere}.monitor-status-orbit{display:grid;place-items:center;flex:0 0 36px;height:36px;border-radius:11px;background:var(--s-bg);color:var(--monitor-dim)}.monitor-status-orbit svg{width:20px}.monitor-status-orbit.enabled{background:color-mix(in srgb,var(--monitor-green) 12%,var(--s-panel));color:var(--monitor-green)}.monitor-status-orbit.running{box-shadow:0 0 0 4px color-mix(in srgb,var(--monitor-green) 7%,transparent)}.monitor-switch{width:36px;height:21px;flex-shrink:0;position:relative;border:0;border-radius:20px;background:color-mix(in srgb,var(--monitor-dim) 38%,var(--s-panel));padding:3px;transition:background .2s}.monitor-switch span{display:block;height:15px;width:15px;border-radius:50%;background:var(--s-panel);box-shadow:0 1px 3px #0002;transition:transform .2s}.monitor-switch[aria-checked=true]{background:var(--s-accent)}.monitor-switch[aria-checked=true] span{transform:translateX(15px);background:var(--s-on-accent,#fff)}
.monitor-settings{margin-top:12px;padding:4px 20px 18px;background:var(--s-panel);border:1px solid var(--s-border);border-radius:12px}.monitor-policy-row{justify-content:space-between;gap:20px;padding:15px 0;border-bottom:1px solid var(--s-border)}.monitor-policy-row strong{font-size:12px;font-weight:550}.monitor-policy-row p{font-size:11px;color:var(--monitor-dim);line-height:1.6;margin:5px 0 0}.monitor-budget{display:flex;align-items:end;gap:15px;flex-wrap:wrap;padding-top:17px}.monitor-budget label{display:grid;grid-template-columns:90px 20px;gap:7px;font-size:11px;color:var(--monitor-dim)}.monitor-budget input{grid-column:1;padding:7px 9px;width:90px;border:1px solid var(--s-border);border-radius:6px;font:inherit;color:var(--s-text);background:var(--s-bg)}.monitor-budget small{align-self:center}.monitor-budget>.monitor-button{margin-left:auto}
.monitor-metrics{display:grid;grid-template-columns:1fr 1fr 1fr 1.25fr;gap:1px;border:1px solid var(--s-border);border-radius:12px;overflow:hidden;background:var(--s-border);margin:16px 0 22px}.monitor-metrics>div{padding:17px 20px;background:var(--s-panel);min-width:0}.monitor-metrics span,.monitor-metrics small{display:block;font-size:10px;color:var(--monitor-dim)}.monitor-metrics strong{display:block;font-size:26px;font-weight:550;font-variant-numeric:tabular-nums;line-height:1.3;letter-spacing:-.6px;margin:6px 0}.monitor-metrics em{font-size:12px;color:var(--monitor-dim);font-style:normal;font-weight:400;letter-spacing:0;margin-left:4px}.monitor-metrics small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.monitor-last-check strong{font-size:13px;letter-spacing:0;line-height:34px}
.monitor-workspace{display:grid;grid-template-columns:minmax(250px,.8fr) minmax(0,1.7fr);gap:18px;align-items:start}.monitor-queue,.monitor-detail{border:1px solid var(--s-border);border-radius:12px;background:var(--s-panel);overflow:hidden}.monitor-queue>header{justify-content:space-between;padding:15px 16px 10px}.monitor-queue h2{margin:0;font-size:12px;font-weight:600}.monitor-queue h2 span{font-weight:400;color:var(--monitor-dim);margin-left:7px;font-size:10px}.monitor-icon{border:0;background:transparent;padding:4px;display:flex;color:var(--monitor-dim)!important;border-radius:5px}.monitor-icon svg{height:14px;width:14px}.monitor-icon:hover{background:var(--s-accent-soft)}.monitor-filters{display:flex;gap:5px;padding:0 16px 14px;border-bottom:1px solid var(--s-border)}.monitor-filters button{font-size:10px;padding:5px 9px;border:1px solid transparent;background:transparent;color:var(--monitor-dim);border-radius:6px}.monitor-filters button.selected{background:var(--s-accent-soft);border-color:color-mix(in srgb,var(--s-accent) 23%,transparent);color:var(--s-text)}.monitor-issue-list{max-height:660px;overflow:auto}.monitor-issue{display:block;text-align:left;width:100%;border:0;border-bottom:1px solid var(--s-border);padding:15px 16px;background:transparent;position:relative}.monitor-issue:last-child{border-bottom:0}.monitor-issue:hover{background:color-mix(in srgb,var(--s-accent-soft) 50%,transparent)}.monitor-issue.selected{background:color-mix(in srgb,var(--s-accent-soft) 70%,var(--s-panel))}.monitor-issue.selected:before{content:'';position:absolute;left:0;top:15px;bottom:15px;width:3px;background:var(--s-accent);border-radius:0 3px 3px 0}.monitor-issue-top,.monitor-issue-bottom{justify-content:space-between;gap:8px}.monitor-issue time{font-size:9px;color:var(--monitor-dim);white-space:nowrap}.monitor-issue>strong{display:block;font-size:12px;font-weight:550;line-height:1.6;margin:9px 0 5px;overflow-wrap:anywhere}.monitor-issue>p{font-size:11px;line-height:1.6;margin:0 0 11px;color:var(--monitor-dim);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}.monitor-issue-bottom span{min-width:0;text-overflow:ellipsis;white-space:nowrap;overflow:hidden;font-size:10px;color:var(--monitor-dim)}.monitor-issue-bottom small{font-size:9px;color:var(--monitor-dim);white-space:nowrap}.monitor-phase{display:inline-flex;align-items:center;gap:5px;font-size:10px;line-height:1.6;color:var(--monitor-dim);white-space:nowrap}.monitor-phase i{display:inline-block;width:5px;height:5px;border-radius:50%;background:currentColor}.monitor-phase[data-phase=applied],.monitor-phase[data-phase=resolved]{color:var(--monitor-green)}.monitor-phase[data-phase=failed]{color:var(--monitor-red)}.monitor-phase[data-phase=waiting]{color:var(--monitor-amber)}.monitor-phase[data-phase=analyzing],.monitor-phase[data-phase=repairing],.monitor-phase[data-phase=verifying]{color:var(--s-accent)}
